import {registerTerm1Offline} from './term1-offline.mjs';
import {registerTerm2Offline} from './term2-offline.mjs';
import {registerMiniOffline} from './mini-offline.mjs';

const offline = {pool,secret,assets,prepare,load,transaction,serialize,resultFor,limiter,readLimiter,draftLimiter,record,onWriting};
registerTerm1Offline(router,offline);
registerTerm2Offline(router,offline);
registerMiniOffline(router,offline);
const runTables = new Map([
  ['term-test-1-k56','term1_offline_run'],
  ['term-test-2-k56','term2_offline_run'],
  ['mini-test-k56','mini_k56_offline_run']
]);
async function assertLegacyWrite(client, slug, attemptId) {
  const table = runTables.get(slug);
  if (!table || !attemptId) return;
  const found = await client.query('SELECT 1 FROM assessment.'+table+' WHERE attempt_id=$1', [attemptId]);
  if (found.rows.length) throw failure('OFFLINE_RELOAD_REQUIRED','Hãy tải lại để tiếp tục lượt đã lưu trên thiết bị.');
}

const result = resultFor(a);
const writing = a.listening_interrupted_at && a.writing_started_at ? {
  task1: String(a.writing_task_1 || ''), task2: String(a.writing_task_2 || ''),
  revision: Number(a.writing_draft_revision) || 0, started: true, submitted: Boolean(a.writing_submitted_at),
  deadlineAt: a.writing_deadline_at || null, serverNow: a.server_now,
  updatedAt: a.writing_updated_at || null, submittedAt: a.writing_submitted_at || null,
  grading: a.writing_submitted_at ? await readWriting(a) : null
} : null;
res.json({ ...serialize(a), className:a.class_name_snapshot, result,
  portalSyncStatus:await readPortalSyncStatus(a,result), exam:serialize(a), writing });
